architecture.h4_f:
msj = CBOR{v:1, texto, responder_a, enviado_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {texto cifrado: hexadecimal(ct), nonce: hexadecimal}

cryptoWire.h1_f:
pt = CBOR{v:1, texto, responder_a?, thread_id?, ¿menciones?, enviado_at}
ct = AES-GCM-256-Encrypt(clave_habitación, nonce, pt, aad=hex(id_habitación))
alambre = CBOR{
  v: 1,
  texto cifrado: hexadecimal(ct), // longitud variable
  nonce: hexadecimal (12 B),
  sender_pseudo: hexadecimal (16 B),
  enviado_at: unix_ms
}

cryptoWire.h5_f:
exterior = CBOR{
  nodo_fuente: hex32,
  usuario_objetivo: int64,
  texto_cifrado interno: bytes,
  internal_nonce: bytes,
  enviado_at: unix_ms
}
sig = Ed25519-Sign(source_priv, exterior)
POST /federación/entregar { sobre: exterior, sig: hex64 }

auth.h1_f:
POST /api/autenticación/registro
  { nombre de usuario, contraseña, x25519_public_key, display_name, ¿teléfono?, ¿correo electrónico?, avatar_emoji }

Respuesta 201 creada:
  {token_acceso, token_actualización, id_usuario, nombre de usuario, ...}

auth.h3_f:
carga útil del token de acceso:
  { sub: user_id, jti: device_id, typ: "acceso", exp: ahora + 15 min }
carga útil de refresco_token:
  { sub: user_id, jti: device_id, typ: "refresh", exp: ahora + 30d }

HS256: firmado con el secreto de 64 bytes del nodo de .env

auth.h4_f:
registrarse_begin(): desafío = rand(32)
                    opciones = { rp.id, user.id, pubKeyCredParams, desafío }
                    opciones de devolución

registrar_finish(certificación):
  verificar la certificación con TPM / raíz de Secure Enclave CA
  almacenar {credential_id, public_key, contador: 0}

auth.h7_f:
POST /api/autenticación/qr/begin
  → { nonce: hexadecimal de 128 bits, ttl: 60 }
QR carga útil = { nonce, user_id, servidor: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → nuevo dispositivo registrado; Los JWT regresaron.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hexadecimal
texto cifrado = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Marco de distribución: { tipo: "m", habitación, mensaje: {id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {nombre de archivo, tamaño, sugerencia_tamaño_fragmento}
            ← {upload_id, tamaño_fragmento}
fragmento PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalizar POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {id_archivo, URL}
TTL en inacabado: 24 h

files.h4_f:
lista_denegada = {
  "aplicación/x-dosexec",
  "aplicación/x-sharedlib",
  "aplicación/x-mach-binary",
}
si magic.from_buffer(buf[:1024]) en deny_list: devuelve 415

presence.h1_f:
cliente: en la primera pulsación de tecla → enviar {tipo:"t", estado:"inicio"}
         no más envíos durante 3 s a menos que cambie el estado
         10 s después de la última pulsación de tecla → enviar {tipo:"t", estado:"detener"}
Receptor: parada automática 10 s después del último "inicio" si no llega ninguna "parada"

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS transmitir {tipo:"c", tipo:"invitar", call_id}
WS transmisión {tipo:"c", tipo:"oferta", sdp}
WS transmisión {tipo:"c", tipo:"respuesta", sdp}
WS transmisión {tipo:"c", tipo:"candidato",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
sobre = {
  nodo_fuente: hex32,
  usuario_objetivo: int64,
  texto_cifrado interno: bytes,
  internal_nonce: bytes,
  enviado_at: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(sobre))
POST /federación/entregar { sobre, firma }

gossip.h3_f:
anuncio = {pubkey, endpoint, publicidad_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(anuncio))
carga útil de chismes: [..., {ad, sig}, ...]

receptor: verificar firma contra ad.pubkey → almacenar si está bien
adicional: PoW de 2^18 ceros a la izquierda en {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template con {
  aleatorio = nuestro azar,
  nombre_servidor = nuestro nombre de host (o envuelto en ECH),
  session_id = nuestra identificación de sesión,
}
JA4 = t13d_xxxx_xxxx_xxxx (coincide con la versión estable actual de Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {nombre: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: dominio(t) = base32( SHA256(semilla ∥ YYYY-MM-DD) )[:16] + ".ejemplo"

push.h4_f:
iOS NSE: didReceive(solicitud) { descifrar(solicitud.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
herramienta = signo_herramienta
entrada = árbol de fuentes, claves/liberación.clave
manifiesto = {
  versión: "0.1.0",
  construido_at: unix_ms,
  archivos: [{ruta, sha256, tamaño}, ...]
}
sig = Ed25519-Sign(liberación_priv, CBOR(manifiesto))
salida = INTEGRITY.sig.json = {manifiesto, firmado_por: pub_hex, sig: sig_hex}

bots.h1_f:
crear: POST /api/bots {nombre de usuario, nombre_visualización, código}
          → {bot_id, token, clave pública}
ejecutar: en proceso (corrutina dentro del nodo)
      OR externo (encuesta larga /api/bots/{id}/updates, token-auth'd)
mensaje: {texto, firma: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
en /inicio {
  emitir "Bienvenido, {ctx.first_name}"
}
en /agregar <elemento> {
  estado.lista = (estado.lista o []) + [ctx.args.item]
  emitir "Agregado: {ctx.args.item}"
}

security.h4_f:
canario.txt (diario):
  {fecha, firma: Ed25519-Sign(release_priv, fecha)}
el cliente verifica → ausente o inválido ⇒ se sospecha compromiso

emergencia:
  administrador POST /api/admin/revoke-all {motivo}
  el nodo transmite {tipo: "n", evento: "compromiso", motivo}
  Los clientes borran claves y fuerzan el reinicio.

debugging.h2_f:
histogramas de velocidad (por ruta + método):
  vortex_http_requests_total{ruta,método,estado}
  vortex_http_request_duration_segundos_bucket{ruta,método,le}

medidores de websocket:
  vortex_ws_connections{nodo}
  vortex_ws_fanout_queue_profundidad{habitación,usuario}

contadores personalizados:
  vortex_messages_sent_total{tipo_habitación}
  vortex_calls_started_total{tipo}

